if (path === "/api/routers") {
          const [inventory, units] = await Promise.all([
            loadRouterInventory(fetch, context.headers),
            platformAll("equipment_units?select=id,unit_number&organization_id=eq." + ORGANIZATION_ID + "&order=id.asc")
          ]);
          const devices = inventory.devices || [];
          const extra = devices.filter((device) => !units.some((unit) => routerJoinKey(unit.unit_number) === routerJoinKey(device.unit_key))).map((device) => ({ id: "camera-device:" + String(device.id), unit_number: String(device.unit_key || "") })).filter((unit) => unit.unit_number.trim());
          return json(presentRouterPage(routerSnapshot(inventory.routers, units.concat(extra)), inventory.routers, devices, context.legacyOwner ? "owner" : "it"));
        }
